<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue';
import { RefreshCw,Upload,Plus,Minus,ArrowRight,History,Undo2,ShieldAlert,Check,FileCheck,GitCompareArrows,ChevronRight } from '@lucide/vue';
import { desk,safely,scan,publish,request,apiPath,loadProject,history,restorePreview,getHistoryFiles,notify,operation } from './store';
import { bytes,when,nameOf,newestReleases,changedFileSize,type Data } from './model';
import {policyPresentation,operationKinds} from './presentation';
const filter=ref('all'),ack=ref(false),selectedRelease=ref<Data|null>(null),reason=ref(''),badVersions=ref<Data[]>([]);
const preview=computed(()=>desk.project?.preview);
const fileSize=(change:Data)=>changedFileSize(change,preview.value?.files,desk.releaseFiles);
const changedBytes=computed(()=>preview.value?.changedFileBytes??(preview.value?.changes||[]).filter((c:Data)=>c.kind==='ADDED'||c.kind==='MODIFIED').reduce((total:number,c:Data)=>total+(fileSize(c)||0),0));
const policies=computed(()=>(preview.value?.policyChanges||[]).map((c:Data)=>policyPresentation(c,desk.project?.maintenance)));
const fileChanges=computed(()=>(preview.value?.changes||[]).filter((c:Data)=>c.kind!=='POLICY_CHANGED'||!policies.value.some((p:any)=>p.subject===c.path)));
const changes=computed(()=>fileChanges.value.filter((c:Data)=>filter.value==='all'||c.kind===filter.value));
const operationSearch=ref(''),operationFilter=ref('all');
const operations=computed(()=>desk.operations.filter(item=>(operationFilter.value==='all'||item.kind===operationFilter.value)&&`${item.title} ${JSON.stringify(item.changes)}`.toLowerCase().includes(operationSearch.value.toLowerCase())));
const releases=computed(()=>newestReleases(desk.project?.releases));
const count=(kind:string)=>(preview.value?.changes||[]).filter((c:Data)=>c.kind===kind).length;
async function removal(path:string,action:string){const p=preview.value;const decisions=p.changes.filter((c:Data)=>c.kind==='REMOVED').map((c:Data)=>({path:c.path,action:c.path===path?action:c.removalAction})).filter((c:Data)=>c.action);desk.project!.preview=await request(apiPath('/removals'),'POST',{previewId:p.previewId,previewDigest:p.previewDigest,decisions});}
async function rollback(release:Data){desk.dialog='rollback';desk.dialogData={release,version:'',notes:''};}
async function problemAction(){if(!badVersions.value.length)return;desk.dialog='problem-confirm';desk.dialogData={versions:badVersions.value,reason:reason.value};}
const kinds:Record<string,string>={ADDED:'新增',MODIFIED:'更新',REMOVED:'移除',METADATA_CHANGED:'信息',POLICY_CHANGED:'维护方式'};
const historyRelease=ref(''),historySearch=ref('');
const historyFiles=computed(()=>desk.releaseFiles.map(file=>({...file,path:file.path,versions:(file.versions||[]).filter((v:Data)=>!historyRelease.value||v.releaseIds?.includes(historyRelease.value))})).filter(f=>f.versions.length&&f.path.toLowerCase().includes(historySearch.value.toLowerCase())));
watch(()=>desk.projectId,()=>{selectedRelease.value=null;badVersions.value=[];historyRelease.value='';});
async function revoke(id:string,correction=false){if(!confirm('结束这个处理要求？发布后生效。'))return;await operation(async()=>{await request(apiPath(correction?'/maintenance/correction-revoke':'/maintenance/withdrawal-revoke'),'POST',{id});await loadProject();await getHistoryFiles();notify('处理要求已结束，检查并发布后生效');});}
</script>
<template>
 <section v-if="desk.section==='changes'" class="changes-workspace">
  <div class="change-review"><header class="view-toolbar"><div><strong>本次改动</strong><span v-if="preview">检查于 {{when(preview.createdAt)}}</span></div><button :disabled="desk.busy" @click="safely(scan)"><RefreshCw :size="15"/>重新检查</button></header>
   <div class="change-filters"><button :class="{selected:filter==='all'}" @click="filter='all'">全部 {{fileChanges.length+policies.length}}</button><button :class="{selected:filter==='ADDED'}" @click="filter='ADDED'"><Plus :size="12"/>新增 {{count('ADDED')}}</button><button :class="{selected:filter==='MODIFIED'}" @click="filter='MODIFIED'">更新 {{count('MODIFIED')}}</button><button :class="{selected:filter==='REMOVED'}" @click="filter='REMOVED'"><Minus :size="12"/>移除 {{count('REMOVED')}}</button></div>
   <div class="diff-list"><article v-for="change in changes" :key="change.path" class="diff-entry"><span class="diff-symbol" :class="change.kind.toLowerCase()"><Minus v-if="change.kind==='REMOVED'" :size="15"/><Plus v-else-if="change.kind==='ADDED'" :size="15"/><ArrowRight v-else :size="15"/></span><div><strong>{{change.displayName||nameOf(change.path)}}</strong><small>{{change.path}}</small><p v-if="change.previousVersion&&change.version">{{change.previousVersion}} <ArrowRight :size="11"/> {{change.version}}</p></div><span class="diff-kind">{{kinds[change.kind]||'设置'}}</span><span class="subtle tabular">{{fileSize(change)!==null?bytes(fileSize(change)!):'—'}}</span><select v-if="change.kind==='REMOVED'" :value="change.removalAction||''" aria-label="移除后如何处理" @change="safely(()=>removal(change.path,($event.target as HTMLSelectElement).value))"><option value="" disabled>选择处理方式</option><option value="DELETE">移除玩家副本</option><option value="RELEASE">留给玩家</option></select></article>
    <article v-for="(rule,i) in policies" :key="i" v-show="filter==='all'" class="policy-diff"><ShieldAlert :size="16"/><div><span class="policy-category">{{rule.label}}</span><strong>{{rule.subject}}</strong><small>{{rule.detail}}</small></div></article>
    <div v-if="!changes.length&&(filter!=='all'||!policies.length)" class="empty-list"><FileCheck :size="36"/><strong>{{desk.busy?'正在检查…':filter!=='all'?'没有这类改动':'与当前发布一致'}}</strong><span>修改文件或维护设置后，变化会显示在这里。</span></div>
   </div><footer class="view-footnote">新增 / 更新文件大小 <strong>{{bytes(changedBytes)}}</strong></footer>
  </div>
  <aside class="release-composer"><span class="overline">发布给玩家</span><h2>准备新版本</h2><p>确认左侧改动，再写下这次更新的内容。</p><label>版本号<input v-model="desk.releaseVersion" placeholder="例如 1.0.1" required></label><label>更新说明<textarea v-model="desk.releaseNotes" rows="8" placeholder="告诉玩家，这次更新了什么"></textarea></label>
   <div v-if="preview?.warnings?.length" class="release-warnings"><p v-for="(warning,i) in preview.warnings" :key="i">{{warning.message||warning.description||warning.code||warning}}</p></div>
   <label v-if="preview?.requiresPlayerUpgrade" class="check"><input v-model="ack" type="checkbox">玩家将获得 {{preview.policyPlayerVersion}} 或更新的玩家端</label><div class="composer-bottom"><span>最低玩家端 {{preview?.policyPlayerVersion||'0.2.0'}}</span><button class="accent full" :disabled="desk.busy||!preview||!desk.releaseVersion||(preview.requiresPlayerUpgrade&&!ack)" @click="safely(()=>publish(ack))"><Upload :size="16"/>发布新版本</button></div>
  </aside>
 </section>
 <section v-else-if="desk.section==='releases'" class="versions-workspace"><div class="version-list"><header class="view-toolbar"><strong>发布版本</strong><span>{{releases.length}} 个</span></header><button v-for="(release,i) in releases" :key="release.releaseId" :class="{current:(selectedRelease||releases[0])?.releaseId===release.releaseId}" @click="selectedRelease=release"><strong>{{release.displayVersion}}</strong><span v-if="i===0" class="current-tag">当前</span><small>{{when(release.createdAt)}} · #{{release.sequence}}</small></button></div>
  <div class="version-detail" v-if="selectedRelease||releases.length"><span class="overline">不可变发布</span><h2>{{(selectedRelease||releases[0]).displayVersion}}</h2><p>{{when((selectedRelease||releases[0]).createdAt)}}</p><pre class="release-notes">{{(selectedRelease||releases[0]).changelog||'此版本没有填写更新说明。'}}</pre><div class="detail-action-row"><button @click="safely(()=>rollback(selectedRelease||releases[0]))"><Undo2 :size="16"/>以此版本创建回滚发布…</button><button @click="desk.view='delivery';desk.section='deployment'"><Upload :size="15"/>发放部署包</button></div><dl class="metadata-list"><dt>发布标识</dt><dd>{{(selectedRelease||releases[0]).releaseId}}</dd><dt>清单 SHA</dt><dd>{{(selectedRelease||releases[0]).manifestSha256}}</dd></dl></div>
  <div v-else class="empty-list"><History :size="36"/><strong>还没有发布记录</strong><span>检查改动，发布第一个版本。</span></div>
 </section>
 <section v-else-if="desk.section==='operations'" class="history-workspace"><header class="view-toolbar"><div><strong>操作记录</strong><span>文件与设置的改动 · {{operations.length}} 条</span></div><button :disabled="desk.busy||!releases.length" @click="safely(()=>restorePreview())"><Undo2 :size="15"/>恢复当前发布设置…</button><button class="icon-button" aria-label="刷新操作记录" :disabled="desk.historyLoading" @click="safely(history)"><RefreshCw :size="15" :class="{spin:desk.historyLoading}"/></button></header>
  <div class="file-actions operation-filters"><label class="file-search"><input v-model="operationSearch" placeholder="搜索文件、设置或操作" aria-label="搜索操作记录"></label><select v-model="operationFilter" aria-label="筛选操作记录"><option value="all">全部操作</option><option value="FILES">文件操作</option><option value="SETTINGS">设置修改</option><option value="PUBLISH">版本发布</option></select></div>
  <div class="operation-list"><article v-for="item in operations" :key="item.id"><div class="operation-marker"><History :size="15"/></div><div><strong>{{item.title||'工作区操作'}}</strong><small>{{when(item.createdAt)}} · {{item.undone?'已撤销':operationKinds[item.kind]||'其他操作'}}</small><details v-if="item.changes?.length"><summary>查看 {{item.changes.length}} 项变化</summary><div class="operation-diffs"><div v-for="(change,i) in item.changes" :key="i"><strong>{{change.setting}}</strong><span>{{change.before||'未设置'}}</span><ArrowRight :size="13"/><span>{{change.after||'未设置'}}</span></div></div></details><p v-if="item.undoUnavailableReason" class="operation-unavailable">{{item.undoUnavailableReason}}</p></div><button v-if="!item.undone&&item.canUndo" :disabled="desk.busy" @click="safely(()=>restorePreview(item.id))">撤销…</button></article><div v-if="!operations.length" class="empty-list"><History :size="36"/><strong>{{desk.historyLoading?'正在读取操作记录…':operationSearch||operationFilter!=='all'?'没有匹配的记录':'还没有操作记录'}}</strong><span>文件与设置的改动会保留在这里。</span></div></div></section>
 <section v-else class="problem-workspace"><header class="view-toolbar"><div><strong>历史问题文件</strong><span>处理以前已留给玩家、后来出问题的文件版本</span></div><button @click="safely(getHistoryFiles)"><RefreshCw :size="15"/>刷新历史</button></header><div class="problem-intro"><ShieldAlert :size="21"/><p>从过去的发布中选择坏版本。即使文件早已停止维护，要求仍会在发布后处理匹配的玩家副本。</p></div><div class="file-actions"><select v-model="historyRelease" aria-label="按发布版本查看历史"><option value="">全部发布版本</option><option v-for="r in releases" :key="r.releaseId" :value="r.releaseId">{{r.displayVersion}} · #{{r.sequence}}</option></select><label class="file-search"><input v-model="historySearch" aria-label="搜索历史文件" placeholder="搜索历史文件路径"></label></div><div class="history-file-list"><article v-for="file in historyFiles" :key="file.path"><strong>{{file.path}}</strong><label v-for="version in file.versions||[]" :key="version.sha256" class="history-version"><input type="checkbox" :disabled="Boolean(version.withdrawnBy)" :checked="badVersions.some(v=>v.sha256===version.sha256&&v.path===file.path)" @change="badVersions=($event.target as HTMLInputElement).checked?[...badVersions,{path:file.path,sha256:version.sha256}]:badVersions.filter(v=>v.sha256!==version.sha256||v.path!==file.path)"><span>{{version.version||version.sha256.slice(0,10)}}</span><small>{{bytes(version.size)}} · {{version.firstRelease}} 至 {{version.lastRelease}}{{version.withdrawnBy?' · 已在处理':''}}</small></label></article><details class="advanced"><summary>正在生效的处理要求 · {{(desk.project?.maintenance?.withdrawals?.length||0)+(desk.project?.maintenance?.corrections?.length||0)}} 项</summary><div v-for="rule in desk.project?.maintenance?.withdrawals||[]" :key="rule.id" class="requirement-row"><div><strong>{{rule.reason||'移除要求'}}</strong><small>{{rule.items?.map((i:any)=>i.path).join('、')}}</small></div><button @click="safely(()=>revoke(rule.id))">结束要求…</button></div><div v-for="rule in desk.project?.maintenance?.corrections||[]" :key="rule.id" class="requirement-row"><div><strong>{{rule.path}}</strong><small>{{rule.reason||'文件修复'}}</small></div><button @click="safely(()=>revoke(rule.id,true))">结束要求…</button></div></details></div><div class="problem-footer"><input v-model="reason" placeholder="问题说明，例如会导致崩溃"><button class="accent" :disabled="!badVersions.length" @click="safely(problemAction)">处理选中的坏版本…</button></div></section>
</template>
